-- Resources content for Sourcework pieces (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or script block by block, trim clips in place, and keep every version.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a wrap, voicer or script you build from your own narration and the project's excerpts. It starts blank and you write it block by block."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type. The Pieces list shows each piece's length and when it last changed."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose Excerpt to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time. Select "},{"type":"text","text":"Set a target","marks":[{"type":"bold"}]},{"type":"text","text":" to give the piece a length such as 1:00 and see how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History","marks":[{"type":"bold"}]},{"type":"text","text":" lists the versions with who saved each one. "},{"type":"text","text":"Restore","marks":[{"type":"bold"}]},{"type":"text","text":" saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-11-sourcework-pieces',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-11',
  p_title => 'Sourcework: pieces',
  p_guide_slugs => array['sourcework-pieces'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework projects have a new Pieces tab. A piece is a wrap, voicer or script written by hand from narration and the project's excerpts, with trimming in place, a running length against a target, saved versions, and copy as text."}]}]}$body$
);
